SINA_SMART["physics1-diffusion"] = {"lecture":"physics1-diffusion","title":"Membranes and simple elementary phenomena","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physics1-diffusion:e0","text":"Membrane: thickness d, mobility u, D = RTu, permeability P = D/d.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-diffusion:e1","text":"Semipermeable (solvent), dialysis (not macromolecules), selective.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-diffusion:e2","text":"Passive: down gradients, no energy; active: ATP, against gradients.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-diffusion:e3","text":"Diffusion: concentration or partial pressure gradient (Fick).","topic":"Elementary passive phenomena","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-diffusion:e4","text":"Convection: Φ = K·S·(P₁ − P₂).","topic":"Elementary passive phenomena","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-diffusion:e5","text":"Electrical migration: potential gradient; electrochemical: both.","topic":"Elementary passive phenomena","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-diffusion:e6","text":"Equilibrium potential (Nernst): E = (RT/zF) ln(C₁/C₂).","topic":"Membrane potentials","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-diffusion:e7","text":"Donnan: impermeant macro-ions unbalance small ions.","topic":"Membrane potentials","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-diffusion:e8","text":"Diffusion potential: ions with different mobilities.","topic":"Membrane potentials","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1jmf34z":"a","1jsmvrz":"a","1dx9ici":"a","11cjlyx":"a","okfmgz":"a","h6t2as":"a","aq77n0":"a","z9pg7d":"a","bnyoob":"a","1cty60o":"a","7aiscm":"a"},"mapCounts":{"verified":0,"auto":11,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physics1-diffusion:e0":{"s":0,"u":["Membrane: thickness d, mobility u, D = RTu, permeability P = D/d.","A membrane is an interface between two compartments, characterised by its thickness d, the mobility uᵢ of particles crossing it, the diffusion coefficient Dᵢ = RT·uᵢ and the permeability Pᵢ = Dᵢ/d ."],"dp":[]},"physics1-diffusion:e1":{"s":0,"u":["Semipermeable (solvent), dialysis (not macromolecules), selective.","Membranes may be semipermeable (solvent only), dialysis (solvent, small molecules and ions, not macromolecules) or selective (certain ions or molecules only)."],"dp":[]},"physics1-diffusion:e2":{"s":0,"u":["Passive: down gradients, no energy; active: ATP, against gradients.","Transfers are passive (no energy, down a gradient: diffusion, facilitated diffusion, osmosis) or active (proteins using ATP, against a gradient)."],"dp":[]},"physics1-diffusion:e3":{"s":1,"u":["Diffusion: concentration or partial pressure gradient (Fick).","Simple diffusion : molecules or ions move from high to low concentration or partial pressure (Fick's law)."],"dp":[]},"physics1-diffusion:e4":{"s":1,"u":["Convection: Φ = K·S·(P₁ − P₂).","Simple convection : a hydrostatic pressure difference pushes solvent and solutes together: Φ = K·S·(P₁ − P₂) (K permeability coefficient, S area)."],"dp":[]},"physics1-diffusion:e5":{"s":1,"u":["Electrical migration: potential gradient; electrochemical: both.","Electrochemical migration : ions respond to both chemical and electrical gradients (the electrochemical potential gradient).","Electrical migration : ions move under an electric potential gradient: cation flux Φ = −C·S·u·dV/dx, anions the opposite."],"dp":[]},"physics1-diffusion:e6":{"s":2,"u":["Equilibrium potential (Nernst): E = (RT/zF) ln(C₁/C₂).","Equilibrium potential : if a membrane lets only one ion through (e.g.","Its value is given by the Nernst equation, E = (RT/zF)·ln(C₁/C₂) ."],"dp":[{"h":"Why a membrane can have a voltage without any pump","t":"If only K⁺ can cross, K⁺ leaks out down its gradient but its negative partners stay behind. Very few ions need to move before the inside becomes negative enough to pull K⁺ back as hard as the gradient pushes it out. That balance point is the Nernst potential, and it is the basis of the resting membrane potential of nerve and muscle cells. Source: the lecture's equilibrium potential slides."}]},"physics1-diffusion:e7":{"s":2,"u":["Donnan: impermeant macro-ions unbalance small ions.","If the membrane lets small ions through but not macro-ions (proteins), the Donnan equilibrium gives an unequal distribution of small ions and a membrane potential."],"dp":[]},"physics1-diffusion:e8":{"s":2,"u":["Diffusion potential: ions with different mobilities.","Diffusion potentials arise transiently when a cation and anion (or two cations) cross with different mobilities : the faster ion runs ahead, separating charge.","If the membrane lets small ions through but not macro-ions (proteins), the Donnan equilibrium gives an unequal distribution of small ions and a membrane potential."],"dp":[]}},"meta":{"1jmf34z":{"a":"recall","vg":"physics1-diffusion:e0/recall/1"},"1jsmvrz":{"a":"recall","vg":"physics1-diffusion:e1/recall/1"},"1dx9ici":{"a":"recall","vg":"physics1-diffusion:e1/recall/2"},"11cjlyx":{"a":"recall","vg":"physics1-diffusion:e2/recall/1"},"okfmgz":{"a":"recall","vg":"physics1-diffusion:e3/recall/1"},"h6t2as":{"a":"recall","vg":"physics1-diffusion:e4/recall/1"},"aq77n0":{"a":"recall","vg":"physics1-diffusion:e5/recall/1"},"z9pg7d":{"a":"recall","vg":"physics1-diffusion:e6/recall/1"},"bnyoob":{"a":"recall","vg":"physics1-diffusion:e6/recall/2"},"1cty60o":{"a":"relationship","vg":"physics1-diffusion:e7/relationship/1"},"7aiscm":{"a":"recall","vg":"physics1-diffusion:e8/recall/1"}},"explRev":"b637b087b1ea"};
